);

/// Reusable parameter: Jira project key.
const _projectParam = ToolParam(
  name: 'project',
  description: 'The project key (e.g. PROJ)',
  required: true,
);

/// Reusable parameter: optional comma-separated field list.
const _fieldsListParam = ToolParam(
  name: 'fields',
