  Map<String, Future<dynamic> Function(Map<String, dynamic>)>
      _transitionHandlers() => {
            'jira_move_to_status_with_resolution': (a) =>
                _client.moveToStatusWithResolution(
                  a['key'] as String,
                  a['statusName'] as String,
                  a['resolution'] as String,
                ),
          };
}

