+          tool!.params.map((p) => p.name).toList()..sort(),
+          entry.value.toList()..sort(),
+          reason: '${entry.key} parameter names diverge from Java; re-run '
+              'scripts/extract_java_tool_params.py after fixing',
+        );
+      }
+    });
+
