  static String? _repoSegment(String? repo) {
    if (repo == null) return null;
    final parts = repo.split('/');
    if (parts.length != 2 || parts.any((p) => p.trim().isEmpty)) return null;
    return '${parts[0].trim()}/${parts[1].trim()}';
