      for (final j in javaNames) {
        final equiv = _dartEquivalentFor(j, dartNames);
        if (equiv != null) {
          expect(
            dartNames,
            contains(equiv),
            reason: '$j maps to unregistered $equiv',
          );
        }
      }
    });
  });
}

